import{_ as t,o as a,c as s,a2 as l}from"./chunks/framework.CHX4lV2z.js";const u=JSON.parse('{"title":"Plugin Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"plugin-catalog/overview.md","filePath":"plugin-catalog/overview.md","lastUpdated":1789811186000}'),n={name:"plugin-catalog/overview.md"};function i(o,e,r,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="plugin-catalog" tabindex="-1">Plugin Catalog <a class="header-anchor" href="#plugin-catalog" aria-label="Permalink to &quot;Plugin Catalog&quot;">​</a></h1><p>This catalog introduces LightRSI&#39;s context-management preset and user-facing cleanup product. Host adapters provide their installation and runtime integration; availability differs by host.</p><h2 id="available-plugins" tabindex="-1">TokenPilot Preset <a class="header-anchor" href="#available-plugins" aria-label="Permalink to &quot;TokenPilot Preset {#available-plugins}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Preset</th><th style="text-align:left;">Capability</th><th style="text-align:left;">Status</th><th style="text-align:left;">Hosts</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./tokenpilot/overview">TokenPilot</a></td><td style="text-align:left;">Cache-aware context management</td><td style="text-align:left;"><span class="badge-stable">Stable</span></td><td style="text-align:left;">OpenClaw, Codex, Claude Code, DeepSeek Harness</td></tr></tbody></table><p><a href="/LightRSI/hosts/deepseek-harness">DeepSeek Harness</a> provides a native Cordis integration with opt-in context eviction and session status. Capabilities vary by host; see <a href="/LightRSI/hosts/compatibility">Host Compatibility</a>.</p><h2 id="context-cleaner-product" tabindex="-1">Context Cleaner Product <a class="header-anchor" href="#context-cleaner-product" aria-label="Permalink to &quot;Context Cleaner Product&quot;">​</a></h2><p><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> provides an inspect, select, approve, and verify workflow for task-level cleanup. It reuses shared task and host rewrite capabilities. It is a user-facing product, while TokenPilot is a preset of context-management policies.</p><p>Public Cleaner entrypoints are available for OpenClaw, Codex, and Claude Code. DeepSeek Harness currently exposes automatic eviction and session status, but no public Cleaner workflow. See <a href="/LightRSI/user-guide/context-cleaner#supported-hosts">Cleaner host support</a>.</p><h2 id="host-plugins-and-adapters" tabindex="-1">Host Plugins and Adapters <a class="header-anchor" href="#host-plugins-and-adapters" aria-label="Permalink to &quot;Host Plugins and Adapters&quot;">​</a></h2><p>OpenClaw&#39;s native plugin and DeepSeek Harness&#39;s Cordis plugin are host integration mechanisms. Codex uses a local proxy and hooks; Claude Code uses a local gateway and MCP. Installing an adapter does not imply that every preset capability or product entrypoint is available on that host.</p><h2 id="plugin-statuses" tabindex="-1">Status Badges <a class="header-anchor" href="#plugin-statuses" aria-label="Permalink to &quot;Status Badges {#plugin-statuses}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Badge</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><span class="badge-stable">Stable</span></td><td style="text-align:left;">Identifies the established capability described on the page; host-specific support and limitations still apply</td></tr><tr><td style="text-align:left;"><span class="badge-experimental">Experimental</span></td><td style="text-align:left;">Identifies work in progress whose behavior and interfaces may change</td></tr></tbody></table><p>These labels do not guarantee identical support across hosts or a frozen API.</p>',13)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
